def text(x):
    if x is None:
        return ''
    if isinstance(x, (list, tuple, set)):
        return ' '.join([text(i) for i in x])
    if isinstance(x, dict):
        return ' '.join([text(k) + ' ' + text(v) for k, v in x.items()])
    return str(x).lower()

def needverb(tt):
    if 'clean' in tt:
        return 'clean'
    if 'heat' in tt:
        return 'heat'
    if 'cool' in tt:
        return 'cool'
    return ''

def hook(ctx, nb):
    tt = text(getv(ctx, 'task.task_type', ''))
    target = text(getv(ctx, 'task.target_type', ''))
    dest = text(getv(ctx, 'task.destination_type', ''))
    verb = needverb(tt)
    if not verb:
        nb['transform_done'] = True
    act = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    obs = text(ctx.get('observation', ''))
    inv = text(getv(ctx, 'world.inventory', ''))
    if verb and target and act.startswith(verb + ' ') and target in act and 'nothing happens' not in obs:
        nb['transform_done'] = True
    if verb and target and target in obs and ('you ' + verb) in obs and 'using' in obs:
        nb['transform_done'] = True
    pc = getv(ctx, 'world.placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    if pc > nb.get('placed_count', 0):
        nb['placed_count'] = pc
    if target and act.startswith('put ') and target in act and 'you put' in obs:
        nb['placed_count'] = max(nb.get('placed_count', 0), 1)
    carrying = bool(target and target in inv and 'not carrying' not in inv and 'nothing' not in inv)
    wrong = bool(inv and 'nothing' not in inv and 'not carrying' not in inv and target and target not in inv)
    adm = [text(a) for a in (ctx.get('admissible') or [])]
    take_ok = bool(target and any(a.startswith('take ') and target in a for a in adm))
    put_ok = bool(target and dest and any(a.startswith('put ') and target in a and dest in a for a in adm))
    trans_ok = bool(verb and target and any(a.startswith(verb + ' ') and target in a for a in adm))
    if wrong:
        stage = 'wrong_inventory'
    elif carrying and verb and not nb.get('transform_done'):
        stage = 'transform'
    elif carrying and put_ok:
        stage = 'put_target'
    elif carrying:
        stage = 'go_destination'
    elif take_ok:
        stage = 'take_target'
    else:
        stage = 'find_target'
    nb['stage'] = stage
    nb['target_type'] = target
    nb['destination_type'] = dest
    nb['task_type'] = tt
    nb['required_verb'] = verb
    nb['transform_available'] = trans_ok
    nb['put_available'] = put_ok
    nb['target_take_available'] = take_ok
    return None

