def hook(ctx, nb):
    stage = nb.get('stage')
    target = nb.get('target_type') or 'target object'
    dest = nb.get('destination_type') or 'destination'
    verb = nb.get('required_verb') or 'required transform'
    tt = nb.get('task_type') or ''
    msg = ''
    if stage == 'wrong_inventory':
        msg = 'You are carrying a non-target item. Do not place it as the goal; recover by setting it aside only if needed, then find and take the requested ' + target + '.'
    elif stage == 'take_target' and nb.get('target_take_available'):
        msg = 'A requested ' + target + ' is available here. Take the target before continuing the search.'
    elif stage == 'transform' and verb:
        if nb.get('transform_available'):
            msg = 'The required ' + verb + ' action for the ' + target + ' is available now. Use it before putting the item at the destination.'
        else:
            place = 'sinkbasin' if verb == 'clean' else ('microwave' if verb == 'heat' else 'fridge')
            msg = 'Carry the ' + target + ' to a ' + place + ' and use the ' + verb + ' action before placing it at the ' + dest + '.'
    elif stage == 'put_target' and nb.get('put_available'):
        msg = 'You are at the ' + dest + ' with the ' + target + '. Use the put action now instead of taking it back or repeating the transform.'
    elif stage == 'go_destination' and dest:
        msg = 'Carry the ' + target + ' to the ' + dest + ' and put it there; do not place it on other receptacles.'
    elif stage == 'find_target' and 'two' in tt and nb.get('placed_count', 0) > 0:
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and use the same ' + dest + ' destination.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

