    adm = [text(a) for a in (ctx.get('admissible') or [])]
    if not act or not adm:
        return None
    in_adm = bool(getv(ctx, 'action.in_admissible', True))
    if not in_adm and not any(a == act for a in adm):
        return {'kind': 'block_and_prompt', 'message': 'That action is not currently available. Choose an exact admissible action; if the needed transform or put is absent, move to the proper place or find another target.'}
    carrying = bool(target and target in text(getv(ctx, 'world.inventory', '')))
    wrong = bool(target and act.startswith('put ') and target not in act and dest and dest in act)
    if wrong and carrying:
        return {'kind': 'block_and_prompt', 'message': 'Do not place a different object type at the destination. Keep searching for the requested ' + target + '.'}
    if verb and target and act.startswith('put ') and target in act and dest and dest in act and not nb.get('transform_done'):
        return {'kind': 'block_and_prompt', 'message': 'This task requires the ' + verb + ' step before placement. Carry the ' + target + ' to the proper transform place and use the ' + verb + ' action first.'}
    if verb and target and act.startswith(verb + ' ') and target in act and dest and dest in act and verb != 'clean':
        return {'kind': 'block_and_prompt', 'message': 'Do not put the item in the destination before the required transform. Use the transform action at the proper appliance first.'}
    if verb and target and act.startswith(verb + ' ') and target in act and not nb.get('transform_done') and not any(a.startswith(verb + ' ') and target in a for a in adm):
        return {'kind': 'block_and_prompt', 'message': 'The required ' + verb + ' action is not available here. Go to the proper transform place or find another ' + target + ' instead of repeating it.'}
    if verb and target and act.startswith('put ') and target in act and dest and dest in act and nb.get('transform_done') and not any(a.startswith('put ') and target in a and dest in a for a in adm):
        return {'kind': 'block_and_prompt', 'message': 'The destination put is not currently admissible. Stay at the destination and use the listed put action, or recover if the item was misplaced.'}
    return None
